const { chromium } = require("@playwright/test");

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 320, height: 640 } });
  await page.goto("http://localhost:3000", { waitUntil: "networkidle" });

  // click trigger
  const trigger = page.locator("button[aria-label=\"Open command palette\"]");
  await trigger.click();
  await page.waitForSelector("[cmdk-dialog]");
  await page.waitForTimeout(500);

  const info = await page.evaluate(() => {
    const dialog = document.querySelector("[cmdk-dialog]");
    const root = document.querySelector("[cmdk-root]");
    const card = root ? root.querySelector(".max-w-lg") : null;
    const input = document.querySelector("[cmdk-input]");
    const firstItem = document.querySelector("[cmdk-item]");

    const getBox = (el) => el ? el.getBoundingClientRect() : null;
    return {
      windowWidth: window.innerWidth,
      docScrollWidth: document.documentElement.scrollWidth,
      dialogBox: getBox(dialog),
      rootBox: getBox(root),
      cardBox: getBox(card),
      inputBox: getBox(input),
      firstItemBox: getBox(firstItem),
      rootClasses: root ? root.className : null,
      cardClasses: card ? card.className : null,
      rootComputed: root ? {
        width: getComputedStyle(root).width,
        maxWidth: getComputedStyle(root).maxWidth,
        margin: getComputedStyle(root).margin,
        display: getComputedStyle(root).display,
        boxSizing: getComputedStyle(root).boxSizing
      } : null,
      cardComputed: card ? {
        width: getComputedStyle(card).width,
        maxWidth: getComputedStyle(card).maxWidth,
        margin: getComputedStyle(card).margin,
        boxSizing: getComputedStyle(card).boxSizing
      } : null
    };
  });

  console.log(JSON.stringify(info, null, 2));
  await page.screenshot({ path: "/var/folders/f2/x_qrr7lx061_f0qvwpfkdk7m0000gn/T/opencode/repro_320px.png" });
  await browser.close();
})();
'

