const { chromium } = require("@playwright/test");

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 320, height: 640 } });
  await page.goto("http://localhost:3000", { waitUntil: "networkidle" });
  await page.locator("button[aria-label=\"Open command palette\"]").click();
  await page.waitForSelector("[cmdk-dialog]");

  await page.evaluate(() => {
    // 1. Dialog content
    document.querySelector("[cmdk-dialog]").className = "fixed inset-0 z-50 flex items-start justify-center pt-[14vh] px-3 sm:px-4";
    // 2. cmdk root
    document.querySelector("[cmdk-root]").className = "w-full max-w-lg min-w-0";
  });

  const checkOverflow = async (scrollPos) => {
    return await page.evaluate((pos) => {
      const list = document.querySelector("[cmdk-list]");
      if (list && pos !== undefined) list.scrollTop = pos;
      const card = document.querySelector("[cmdk-root] .max-w-lg");
      const bad = [];
      for (const el of card.querySelectorAll("*")) {
        // ignore elements with their own intentional scroll container
        if (el.hasAttribute("cmdk-list")) continue;
        if (el.scrollWidth > el.clientWidth + 1) {
          bad.push({
            tag: el.tagName,
            class: el.className,
            scrollW: el.scrollWidth,
            clientW: el.clientWidth,
            text: el.textContent?.slice(0, 30)
          });
        }
      }
      return {
        cardScrollWidth: card.scrollWidth,
        cardClientWidth: card.clientWidth,
        listScrollWidth: list.scrollWidth,
        listClientWidth: list.clientWidth,
        bad
      };
    }, scrollPos);
  };

  console.log("Top of list:", await checkOverflow(0));
  console.log("Middle of list:", await checkOverflow(300));
  console.log("Bottom of list:", await checkOverflow(1000));

  await browser.close();
})();
'

