    await page.locator("button[aria-label=\"Open command palette\"]").click();
    await page.waitForSelector("[cmdk-dialog]");

    await page.evaluate(() => {
      document.querySelector("[cmdk-dialog]").className = "fixed inset-0 z-50 flex items-start justify-center pt-[14vh] px-4";
      document.querySelector("[cmdk-root]").className = "w-full max-w-lg min-w-0";

      const items = document.querySelectorAll("[cmdk-item]");
      items.forEach(item => {
        // Find label span (the one right after the icon span)
        const spans = item.querySelectorAll(":scope > span");
        if (spans.length >= 2) {
          spans[1].className = "shrink-0 max-w-[60%] sm:max-w-none truncate";
        }
        if (spans.length >= 3) {
          spans[2].className = "min-w-0 flex-1 text-right truncate text-xs text-fg-subtle";
        }
      });
    });

    await page.waitForTimeout(200);

    // Check item bounding boxes
    const itemData = await page.evaluate(() => {
      const res = [];
      document.querySelectorAll("[cmdk-item]").forEach(item => {
        const text = item.textContent;
        if (text.includes("Classic") || text.includes("Developer") || text.includes("Recruiter") || text.includes("Download résumé")) {
          const spans = item.querySelectorAll(":scope > span");
          const label = spans[1];
          const hint = spans[2];
          res.push({
            labelText: label?.textContent,
            labelW: label?.getBoundingClientRect().width,
            hintText: hint?.textContent,
            hintW: hint ? hint.getBoundingClientRect().width : null,
            itemScrollW: item.scrollWidth,
            itemClientW: item.clientWidth
          });
