        if (icon) icon.className = "shrink-0 text-accent";

        const label = item.querySelector(".flex-1");
        const hint = item.querySelector(".text-fg-subtle:not(svg)");
        const arrow = item.querySelector("svg.lucide-arrow-up-right");

