          if (hint) {
            hint.className = "min-w-0 truncate text-xs text-fg-subtle";
            item.removeChild(hint);
            rightGroup.appendChild(hint);
          }
          item.removeChild(arrow);
          arrow.setAttribute("class", "shrink-0 text-fg-subtle");
          rightGroup.appendChild(arrow);
          item.appendChild(rightGroup);
        }
      });
    });

    await page.waitForTimeout(200);

    const positions = await page.evaluate(() => {
      const homeItem = Array.from(document.querySelectorAll("[cmdk-item]")).find(el => el.textContent.trim() === "Home");
      const classicItem = Array.from(document.querySelectorAll("[cmdk-item]")).find(el => el.textContent.includes("Classic view"));
      const homeArrow = homeItem?.querySelector("svg");
      const classicArrow = classicItem?.querySelectorAll("svg")[1];
      const classicHint = classicItem?.querySelector(".text-fg-subtle:not(svg)");

      return {
        cardWidth: document.querySelector("[cmdk-root] .max-w-lg").getBoundingClientRect().width,
        homeArrowRight: homeArrow?.getBoundingClientRect().right,
        classicArrowRight: classicArrow?.getBoundingClientRect().right,
        classicHintRight: classicHint?.getBoundingClientRect().right,
        classicArrowLeft: classicArrow?.getBoundingClientRect().left
      };
    });

    console.log(`=== ${width}px ===`, positions);

    await page.screenshot({
      path: `/var/folders/f2/x_qrr7lx061_f0qvwpfkdk7m0000gn/T/opencode/perfect_${width}px.png`
    });

    await page.close();
  }

  await browser.close();
})();
'

